    /*
     * Add to the ChangeEvents
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	DigitalTwin
     */
    public DigitalTwin addToChangeEvents( UUID parentId, TwinChangeEvent addTo ) {
	    LOGGER.info("handling AssignChangeEventsToDigitalTwinEvent - " );
	    
	    DigitalTwin parentEntity = repository.findById(parentId).get();
	    TwinChangeEvent child = registry.project( TwinChangeEvent.class, addTo.getTwinChangeEventId());
	    
	    parentEntity.getChangeEvents().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the ChangeEvents
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	DigitalTwin
     */
	public DigitalTwin removeFromChangeEvents( UUID parentId, TwinChangeEvent removeFrom ) {
	    LOGGER.info("handling RemoveChangeEventsFromDigitalTwinEvent " );
	
	    DigitalTwin parentEntity = repository.findById(parentId).get();
	    TwinChangeEvent child = registry.project( TwinChangeEvent.class, removeFrom.getTwinChangeEventId());
	    
	    parentEntity.getChangeEvents().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



